func (o *Moeda) SetPais(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*Pais) error {
	query := "update `pais` set `moeda_id` = null where `moeda_id` = ?"
	values := []interface{}{o.MoedaID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.Pais {
			queries.SetScanner(&rel.MoedaID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Moeda = nil
		}
		o.R.Pais = nil
	}

	return o.AddPais(ctx, exec, insert, related...)
}

// RemovePais relationships from objects passed in.
// Removes related items from R.Pais (uses pointer comparison, removal does not keep order)
// Sets related.R.Moeda.
func (o *Moeda) RemovePais(ctx context.Context, exec boil.ContextExecutor, related ...*Pais) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.MoedaID, nil)
		if rel.R != nil {
			rel.R.Moeda = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("moeda_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.Pais {
			if rel != ri {
				continue
			}

			ln := len(o.R.Pais)
			if ln > 1 && i < ln-1 {
				o.R.Pais[i] = o.R.Pais[ln-1]
			}
			o.R.Pais = o.R.Pais[:ln-1]
			break
		}
	}

	return nil
}

// Moedas retrieves all the records using an executor.
func Moedas(mods ...qm.QueryMod) moedaQuery {
	mods = append(mods, qm.From("`moeda`"))
	q := NewQuery(mods...)
	if len(queries.GetSelect(q)) == 0 {
		queries.SetSelect(q, []string{"`moeda`.*"})
	}

	return moedaQuery{q}
}

// FindMoeda retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindMoeda(ctx context.Context, exec boil.ContextExecutor, moedaID int, selectCols ...string) (*Moeda, error) {
	moedaObj := &Moeda{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from `moeda` where `moeda_id`=?", sel,
	)

	q := queries.Raw(query, moedaID)

	err := q.Bind(ctx, exec, moedaObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "models: unable to select from moeda")
	}

	if err = moedaObj.doAfterSelectHooks(ctx, exec); err != nil {
		return moedaObj, err
	}

	return moedaObj, nil
}

